492			return nil, "", errors.Errorf("invalid resource name format: %s", name)
493		}
494	
495		user, err := s.resolveUserFromName(ctx, BuildUserName(parts[1]))
496		if err != nil {
497			return nil, "", err
498		}
499		return user, parts[3], nil
500	}
