528	func convertLinkedIdentityFromStore(user *store.User, identity *store.UserIdentity) *v1pb.LinkedIdentity {
529		return &v1pb.LinkedIdentity{
530			Name:      fmt.Sprintf("%s/linkedIdentities/%s", BuildUserName(user.Username), identity.Provider),
531			IdpName:   IdentityProviderNamePrefix + identity.Provider,
532			ExternUid: identity.ExternUID,
533		}
534	}
