536	func (s *APIV1Service) resolveUserAndNotificationIDFromName(ctx context.Context, name string) (*store.User, int32, error) {
537		parts := strings.Split(name, "/")
538		if len(parts) != 4 || parts[0] != "users" || parts[2] != "notifications" {
539			return nil, 0, errors.Errorf("invalid notification name: %s", name)
540		}
541	
542		user, err := s.resolveUserFromName(ctx, BuildUserName(parts[1]))
543		if err != nil {
544			return nil, 0, err
545		}
546	
547		id, err := strconv.Atoi(parts[3])
548		if err != nil {
549			return nil, 0, errors.Errorf("invalid notification id: %s", parts[3])
550		}
551	
552		return user, int32(id), nil
553	}
